package com.voicetxt.reader;
import android.os.*;import android.content.pm.*;import android.security.NetworkSecurityPolicy;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.JSONObject;import org.apache.commons.compress.archivers.tar.*;import org.apache.commons.lang3.ClassUtils;
/** Defensive input regressions: no user documents or installed models are modified. */
public class SecurityRegressionTest extends VoiceWarmupTest {
 interface Throwing {void run()throws Exception;}
 void rejects(Throwing task,String name)throws Exception{try{task.run();throw new AssertionError(name+" accepted");}catch(IOException expected){}}
 void zip(File file,String name,String content)throws Exception{try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(file))){out.putNextEntry(new ZipEntry(name));out.write(content.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();}}
 public void onStart(){Bundle result=new Bundle();File base=null;boolean success=false;try{base=new File(getTargetContext().getCacheDir(),"security-audit-"+UUID.randomUUID());check(base.mkdirs(),"Test directory unavailable");final File root=base;File extraction=new File(root,"extracted");check(extraction.mkdirs(),"Extraction directory unavailable");File archive=new File(root,"test.zip");zip(archive,"safe.txt","security canary");new VoiceArchive(extraction,()->{}).extract(archive);check(new File(extraction,"safe.txt").isFile(),"Valid ZIP rejected");zip(archive,"nested/../../escape.txt","canary");rejects(()->new VoiceArchive(extraction,()->{}).extract(archive),"ZIP traversal");check(!new File(root,"escape.txt").exists(),"ZIP escaped extraction directory");zip(archive,"C:/escape.txt","canary");rejects(()->new VoiceArchive(extraction,()->{}).extract(archive),"Windows absolute path");zip(archive,"/escape.txt","canary");rejects(()->new VoiceArchive(extraction,()->{}).extract(archive),"Absolute path");File tar=new File(root,"links.tar");try(TarArchiveOutputStream out=new TarArchiveOutputStream(new FileOutputStream(tar))){TarArchiveEntry link=new TarArchiveEntry("escape-link",TarConstants.LF_SYMLINK);link.setLinkName("../escape.txt");out.putArchiveEntry(link);out.closeArchiveEntry();}rejects(()->new VoiceArchive(extraction,()->{}).extract(tar),"TAR symlink");File huge=new File(root,"huge.tar");TarArchiveEntry entry=new TarArchiveEntry("huge.bin");entry.setSize(VoiceArchive.MAX_EXPANDED+1);byte[] header=new byte[512];entry.writeEntryHeader(header);try(FileOutputStream out=new FileOutputStream(huge)){out.write(header);}rejects(()->new VoiceArchive(extraction,()->{}).extract(huge),"Oversized TAR entry");rejects(()->VoiceModel.configured(extraction,new JSONObject().put("tokens","../../outside.txt"),"tokens",null),"Manifest path traversal");zip(archive,"cancelled.txt","canary");rejects(()->new VoiceArchive(extraction,()->{throw new IOException("cancelled");}).extract(archive),"Cancelled extraction");
 VoiceModel nativePaths=new VoiceModel();nativePaths.directory=extraction;check(nativePaths.path("safe.txt").equals(new File(extraction,"safe.txt").getAbsolutePath()),"Valid native path rejected");rejects(()->nativePaths.path("lexicon,other-path.txt"),"Native comma-separated path injection");
 for(String address:new String[]{"http://example.org/model.zip","file:///example/model.zip","https://user:password@example.org/model.zip"})rejects(()->VoicePackages.address(address),"Unsafe URL scheme/credentials");check(VoicePackages.address("https://example.org/model.tar.bz2").getProtocol().equals("https"),"HTTPS rejected");
 check(!NetworkSecurityPolicy.getInstance().isCleartextTrafficPermitted(),"Cleartext network permitted");check((getTargetContext().getApplicationInfo().flags&ApplicationInfo.FLAG_ALLOW_BACKUP)==0,"Backup unexpectedly enabled");PackageInfo components=getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),PackageManager.GET_ACTIVITIES|PackageManager.GET_SERVICES|PackageManager.GET_PROVIDERS|PackageManager.GET_RECEIVERS);for(ActivityInfo activity:components.activities)if(!activity.name.equals(ShelfActivity.class.getName()))check(!activity.exported,"Unexpected exported activity "+activity.name);for(ServiceInfo service:components.services)check(!service.exported||service.permission!=null,"Unguarded exported service "+service.name);for(ProviderInfo provider:components.providers)check(!provider.exported,"Exported provider "+provider.name);
 StringBuilder longName=new StringBuilder();for(int i=0;i<1024;i++)longName.append("p.");longName.append("MissingClassForSecurityRegression");long began=SystemClock.elapsedRealtime();try{ClassUtils.getClass(longName.toString());throw new AssertionError("Nonexistent class loaded");}catch(ClassNotFoundException expected){}result.putLong("longClassNameMs",SystemClock.elapsedRealtime()-began);result.putString("result","PASS: valid ZIP; traversal/absolute paths, TAR symlink and oversized entry rejected; manifest confinement; cancellation; HTTP/file/credential URLs rejected; cleartext and backup disabled; components restricted; long class name handled without stack overflow after dependency fix");success=true;}catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(base!=null)try{VoicePackages.deleteTree(base,getTargetContext().getCacheDir());}catch(IOException error){result.putString("cleanupError",error.toString());success=false;}}finish(success?-1:0,result);}
}
